import os
from pathlib import Path
from typing import Optional, Union, BinaryIO

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def upload_to_s3(
    file_or_stream: Union[str, bytes, bytearray, BinaryIO],
    bucket_name: str,
    object_key: str,
    region_name: Optional[str] = None,
    content_type: Optional[str] = None,
) -> str:
    """
    Upload a file path, byte stream, or bytes-like object to Amazon S3.

    Returns the S3 URI of the uploaded object.
    """
    s3 = boto3.client("s3", region_name=region_name)

    extra_args = {}
    if content_type:
        extra_args["ContentType"] = content_type

    try:
        if isinstance(file_or_stream, str):
            s3.upload_file(file_or_stream, bucket_name, object_key, ExtraArgs=extra_args or None)
        elif isinstance(file_or_stream, (bytes, bytearray)):
            import io

            bio = io.BytesIO(file_or_stream)
            if extra_args:
                s3.upload_fileobj(bio, bucket_name, object_key, ExtraArgs=extra_args)
            else:
                s3.upload_fileobj(bio, bucket_name, object_key)
        else:
            if extra_args:
                s3.upload_fileobj(file_or_stream, bucket_name, object_key, ExtraArgs=extra_args)
            else:
                s3.upload_fileobj(file_or_stream, bucket_name, object_key)

    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Failed to upload to S3: {e}") from e

    return f"s3://{bucket_name}/{object_key}"


def upload_file_to_s3(
    file_path: str,
    bucket_name: str,
    object_key: Optional[str] = None,
    region_name: Optional[str] = None,
    content_type: Optional[str] = None,
) -> str:
    """
    Convenience wrapper for uploading a local file path to Amazon S3.
    """
    if object_key is None:
        object_key = Path(file_path).name
    return upload_to_s3(file_path, bucket_name, object_key, region_name=region_name, content_type=content_type)


def upload_bytes_to_s3(
    data: bytes,
    bucket_name: str,
    object_key: str,
    region_name: Optional[str] = None,
    content_type: Optional[str] = None,
) -> str:
    """
    Convenience wrapper for uploading bytes to Amazon S3.
    """
    return upload_to_s3(data, bucket_name, object_key, region_name=region_name, content_type=content_type)
